<?php
function attPost(array|false $u,string $action,array $p):?string{
 attRequire(attReady(),'Run the database migration first.');
 if($action==='att_qr'){secureDevice();$board=boardDevice();attRequire((bool)$board,'This browser is not a registered classroom board.');db()->beginTransaction();try{$data=issueQr($board);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}$qr=new \Endroid\QrCode\QrCode(data:$data['url'],size:360,margin:16);$png=(new \Endroid\QrCode\Writer\PngWriter())->write($qr);$class=currentClass((int)$board['classroom_id']);header('Content-Type: application/json');echo json_encode(['image'=>$png->getDataUri(),'expires'=>$data['expires'],'ttl'=>attSettings()['qr_seconds'],'class'=>$class?$class['subject_name'].' · '.$class['start_time'].'–'.$class['end_time'].' · '.$class['name']:'No class in the current check-in window']);exit;}
 if($action==='att_confirm'){secureDevice();db()->beginTransaction();try{$id=confirmAttendance(required($p,'token'));db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}return 'Attendance recorded successfully. Reference #'.$id;}
 if($action==='att_enrol'){secureDevice();db()->beginTransaction();try{$raw=consumeEnrolment(required($p,'token'),required($p,'device_name'));db()->commit();setDeviceCookie('__Host-cnr_tutor',$raw);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}return 'Phone enrolled. You can now scan the classroom QR and confirm attendance without signing in.';}
 attRequire((bool)$u,'Sign in first.');db()->beginTransaction();try{attLock();
 if($action==='att_device')throw new RuntimeException('Use an Admin-issued phone enrolment link. No staff login is required.');
 if($action==='att_calendar_save'){saveTeachingCalendar($u,$p);}
 elseif($action==='att_time_save'){saveTeachingTime($u,$p);}
 elseif($action==='att_calendar_retire'){attRequire($u['role']==='admin');$table=($p['kind']??'')==='time'?'teaching_time_slots':'teaching_calendars';q("UPDATE $table SET active=0 WHERE id=?",[(int)$p['id']]);attAudit((int)$u['id'],'Teaching setting retired',(int)$p['id'],['table'=>$table]);}
 elseif($action==='att_permission'){attRequire($u['role']==='admin');$id=(int)$p['staff_id'];$staff=one("SELECT * FROM users WHERE id=? AND role NOT IN ('student','guest') AND active=1",[$id]);attRequire((bool)$staff,'Choose an active staff entry.');$enabled=!empty($p['enabled'])?1:0;if(one('SELECT user_id FROM tutor_permissions WHERE user_id=?',[$id]))q('UPDATE tutor_permissions SET enabled=? WHERE user_id=?',[$enabled,$id]);else q('INSERT INTO tutor_permissions(user_id,enabled) VALUES(?,?)',[$id,$enabled]);if(!$enabled)q('UPDATE tutor_registered_devices SET active=0,revoked_at=? WHERE staff_id=?',[now(),$id]);attAudit((int)$u['id'],'Teaching permission changed',$id,['enabled'=>$enabled]);}
 elseif($action==='att_enrol_link'){$_SESSION['enrol_link']=enrolmentLink($u,(int)$p['staff_id']);}
 elseif($action==='att_room'){attRequire(academic($u));$id=(int)($p['id']??0);$code=required($p,'room_code');attRequire((bool)preg_match('/^[A-Za-z0-9_-]{1,60}$/',$code),'Use letters, numbers, hyphen or underscore for room code.');$values=[$code,required($p,'room_name'),required($p,'building'),required($p,'floor'),!empty($p['active'])?1:0];if($id)q('UPDATE classrooms SET room_code=?,room_name=?,building=?,floor=?,active=? WHERE id=?',[...$values,$id]);else{q('INSERT INTO classrooms(room_code,room_name,building,floor,active,created_at) VALUES(?,?,?,?,?,?)',[...$values,now()]);$id=(int)db()->lastInsertId();}attAudit((int)$u['id'],'Classroom saved',$id);}
 elseif($action==='att_board'){attRequire($u['role']==='admin');secureDevice();$room=(int)$p['classroom_id'];attRequire((bool)one('SELECT id FROM classrooms WHERE id=? AND active=1',[$room]),'Select an active room.');$raw=bin2hex(random_bytes(32));q('INSERT INTO classroom_devices(classroom_id,token_hash,device_name,registered_at) VALUES(?,?,?,?)',[$room,hash('sha256',$raw),required($p,'device_name'),now()]);attAudit((int)$u['id'],'Classroom board registered',(int)db()->lastInsertId());db()->commit();setDeviceCookie('__Host-cnr_board',$raw);return 'Board registered in this browser. Sign out and open Classroom Display.';}
 elseif($action==='att_revoke'){attRequire($u['role']==='admin');$table=($p['kind']??'')==='board'?'classroom_devices':'tutor_registered_devices';$id=(int)$p['id'];q("UPDATE $table SET active=0 WHERE id=?",[$id]);attAudit((int)$u['id'],'Device revoked',$id,['kind'=>$table]);}
 elseif($action==='att_settings'){attRequire($u['role']==='admin');$values=[];foreach(['early_minutes'=>60,'late_minutes'=>60,'close_minutes'=>120,'qr_seconds'=>60]as $k=>$max){$v=filter_var($p[$k]??'',FILTER_VALIDATE_INT);attRequire($v!==false&&$v>=($k==='qr_seconds'?30:0)&&$v<=$max,'Invalid '.$k);$values[$k]=$v;}attRequire($values['late_minutes']<=$values['close_minutes'],'Late threshold must not exceed closing window.');foreach($values as $k=>$v)q('UPDATE attendance_settings SET setting_value=? WHERE setting_key=?',[(string)$v,$k]);attAudit((int)$u['id'],'Settings changed',null,$values);}
 elseif($action==='att_upload'){attRequire(academic($u));unset($_SESSION['att_import']);$f=$_FILES['sheet']??[];attRequire(($f['error']??1)===UPLOAD_ERR_OK&&$f['size']<=10*1024*1024,'Choose an Excel file under 10 MB.');$_SESSION['att_import']=timetablePreview(teachingFileRows($f['tmp_name'],$f['name']),'','');}
 elseif($action==='att_import'){attRequire(!empty($_SESSION['att_import']),'Upload and preview first.');$items=$_SESSION['att_import'];$count=timetableCommit($items,$u);foreach($items as &$item)$item['status']=$item['status']==='Valid'?'Uploaded':'Not uploaded';unset($item);$batch=bin2hex(random_bytes(16));q('INSERT INTO timetable_import_results(id,created_at,actor_id,results) VALUES(?,?,?,?)',[$batch,now(),$u['id'],json_encode($items,JSON_THROW_ON_ERROR)]);db()->commit();unset($_SESSION['att_import']);return $count.' sessions imported. Open Import history below to review uploaded and not uploaded rows and download corrections.';}
 elseif($action==='att_cancel_import'){attRequire(academic($u));unset($_SESSION['att_import']);}
 elseif($action==='att_schedule_add'){attRequire(academic($u));$t=normalizeSchedule(manualClassRow($p),'','');$conflict=scheduleConflict($t,all('SELECT * FROM tutor_timetable WHERE active=1'));attRequire(!$conflict,$conflict??'');$id=insertSchedule($t,(int)$u['id']);attAudit((int)$u['id'],'Timetable entered manually',$id);}
 elseif($action==='att_schedule_edit'){attRequire(academic($u));attLock();$id=(int)$p['id'];$old=one('SELECT * FROM tutor_timetable WHERE id=?',[$id]);attRequire((bool)$old,'Timetable not found.');attRequire(!one('SELECT id FROM tutor_attendance WHERE timetable_id=?',[$id]),'This timetable has attendance. Disable future occurrences and add a new schedule instead.');$t=normalizeSchedule(manualClassRow($p),'','');$conflict=scheduleConflict($t,all('SELECT * FROM tutor_timetable WHERE active=1'),$id);attRequire(!$conflict,$conflict??'');$sets=implode(',',array_map(fn($k)=>$k.'=?',array_keys($t)));q('UPDATE tutor_timetable SET '.$sets.',updated_at=? WHERE id=?',[...array_values($t),now(),$id]);attAudit((int)$u['id'],'Timetable edited',$id,['before'=>$old]);}
 elseif($action==='att_disable'){attRequire(academic($u));q('UPDATE tutor_timetable SET active=0,disabled_at=?,updated_at=? WHERE id=? AND active=1',[now(),now(),(int)$p['id']]);attAudit((int)$u['id'],'Timetable disabled',(int)$p['id']);}
 elseif($action==='att_delete'){attRequire($u['role']==='admin');attLock();$t=one('SELECT * FROM tutor_timetable WHERE id=?',[(int)$p['id']]);attRequire($t&&$t['valid_from']>date('Y-m-d')&&!one('SELECT id FROM tutor_attendance WHERE timetable_id=?',[$t['id']]),'Only future timetables with no attendance can be deleted. Disable this schedule instead.');q('DELETE FROM tutor_timetable WHERE id=?',[$t['id']]);attAudit((int)$u['id'],'Timetable deleted',(int)$t['id'],['before'=>$t]);}
 elseif($action==='att_adjust')adjustAttendance($u,$p);
 else throw new RuntimeException('Unknown attendance action.');db()->commit();return 'Saved successfully.';
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function attDownload(array|false $u,string $page):void{
 attRequire($u&&attAccess($u));
 if($page==='att_grid_template'){attRequire(academic($u));classGridTemplate();}
 if(in_array($page,['att_template','att_csv_template'],true)){attRequire(academic($u));teachingRowTemplate($page==='att_csv_template');}
 if($page==='att_errors'){attRequire(academic($u));$items=!empty($_GET['batch'])?savedImportResult():($_SESSION['att_import']??[]);excelDownload([...attHeaders(),'Original Row','Import Error'],importCorrectionRows($items),'timetable-corrections');}
 if($page==='att_export'){$rows=attendanceReport($u,$_GET);excelDownload(['Timetable','Date','Tutor','Subject','Department','Programme','Room','Start','End','Confirmed','Status','Remarks'],array_map('array_values',$rows),'attendance-report');}
 if($page==='att_schedule_export'){$rows=[];foreach(scheduledRows()as $t)if(attVisible($u,$t))foreach(sessionGroups($t)as $g)$rows[]=[$t['academic_year'],$t['semester'],$g['department'],$g['programme'],$g['year_level'],$g['section'],$t['subject_code'],$t['subject_name'],$t['email'],$t['name'],['','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][$t['weekday']],$t['class_date'],$t['start_time'],$t['end_time'],$t['room_code'],$t['valid_from'],$t['valid_until'],'SESSION-'.$t['id'],$t['student_count']??'',$t['delivery_mode']??'In person',($t['attendance_required']??1)?'Yes':'No',!empty($t['flexible'])?'Yes':'No'];excelDownload(attHeaders(),$rows,'teaching-timetable');}
}
